const body = $input.first().json.body || {};
const jobId = String(body.jobId || "").trim();
const valid = /^JOB-\d{8}-[A-Z2-9]{4}$/.test(jobId);
return [{ json: { valid, jobId, errors: valid ? [] : ["Invalid job."] } }];

const SHELL_CSS = `
  :root{
    --ink:#12213b; --ink-soft:#1d3258; --fog:#f3f5f9; --line:#d3dae6; --steel:#56657e;
    --hl:#ffd93d; --hl-soft:#fff3b8; --danger:#b3261e; --danger-bg:#fdecea;
    --ok:#075e4b; --ok-bg:#d4f0e6;
    --display:'Bricolage Grotesque','Segoe UI',system-ui,sans-serif;
    --body:'Instrument Sans',system-ui,-apple-system,'Segoe UI',sans-serif;
  }
  *{box-sizing:border-box}
  body{margin:0;background:var(--fog);color:var(--ink);font-family:var(--body);font-size:16px;line-height:1.5;
    -webkit-font-smoothing:antialiased}
  button{font:inherit;color:inherit}

  .bar{background:#fff;border-bottom:1px solid var(--line)}
  .bar__in{display:flex;align-items:center;justify-content:space-between;height:64px;padding:0 40px}
  .brand{display:inline-flex;align-items:center;gap:10px;font-family:var(--display);font-weight:700;font-size:20px;letter-spacing:-.02em}
  .brand svg{width:32px;height:32px}

  main{padding:48px 40px 80px}
  h1{margin:0 0 8px;font-family:var(--display);font-size:40px;font-weight:700;line-height:1.1;letter-spacing:-.03em}
  h2{margin:0;font-family:var(--display);font-size:22px;font-weight:700;letter-spacing:-.02em}
  .lede{max-width:48rem;margin:0 0 32px;font-size:17px;color:var(--steel)}

  .panel{background:#fff;border:1px solid var(--line);border-top:4px solid var(--hl);border-radius:12px;padding:28px 32px 32px;margin-bottom:28px}
  .panel__head{display:flex;align-items:baseline;justify-content:space-between;gap:12px;margin-bottom:20px}
  .grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(300px,1fr));gap:16px}
  .job{display:flex;flex-direction:column;border:1px solid var(--line);border-radius:12px;padding:20px;background:#fff;
    transition:border-color .15s,box-shadow .15s}
  .job:hover{border-color:#b3bdcf;box-shadow:0 6px 18px -10px rgba(18,33,59,.25)}
  .top{display:flex;justify-content:space-between;gap:12px;align-items:flex-start}
  .job h3{margin:0 0 4px;font-family:var(--display);font-size:19px;font-weight:700;letter-spacing:-.015em;line-height:1.2}
  .meta{font-size:13px;color:var(--steel)}
  .meta strong{color:var(--ink)}
  .badge{flex:none;padding:3px 10px;border-radius:999px;font-size:12px;font-weight:700;white-space:nowrap;background:var(--fog);color:var(--steel)}
  .badge.open{background:var(--ok-bg);color:var(--ok)}
  .actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:auto;padding-top:18px}
  .btn{height:40px;padding:0 16px;border-radius:8px;font-size:14px;font-weight:600;cursor:pointer;transition:background-color .15s,border-color .15s}
  .btn:focus-visible{outline:3px solid var(--ink);outline-offset:2px}
  .btn:disabled{opacity:.55;cursor:wait}
  .btn-primary{background:var(--ink);color:#fff;border:0}
  .btn-primary:hover:not(:disabled){background:var(--ink-soft)}
  .btn-danger{background:#fff;color:var(--danger);border:1.5px solid #f0c4c0}
  .btn-danger:hover:not(:disabled){background:var(--danger-bg);border-color:var(--danger)}
  .empty{padding:24px;border:1px dashed var(--line);border-radius:12px;text-align:center;color:var(--steel);font-size:15px}

  @media (max-width:860px){h1{font-size:32px}}
  @media (max-width:560px){main{padding:32px 16px 56px}.bar__in{padding:0 16px}.panel{padding:22px 18px 24px}
    .grid{grid-template-columns:1fr}}
  @media (prefers-reduced-motion:reduce){*{transition:none!important}}
`;

const shell = (title, body) => `<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>${title} - Shortlist</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:opsz,wght@12..96,500..800&family=Instrument+Sans:wght@400..700&display=swap" rel="stylesheet"><style>${SHELL_CSS}</style></head><body>
<header class="bar"><div class="bar__in">
  <span class="brand">
    <svg viewBox="0 0 32 32" aria-hidden="true">
      <rect width="32" height="32" rx="8" fill="#12213B"/>
      <rect x="9" y="6" width="14" height="20" rx="2" fill="#F7F8FB"/>
      <rect x="11.5" y="10" width="9" height="2" rx="1" fill="#9AA6BA"/>
      <rect x="8" y="14.5" width="16" height="4.5" rx="1" fill="#FFD93D" opacity=".92"/>
      <rect x="11.5" y="15.5" width="9" height="2" rx="1" fill="#12213B"/>
      <rect x="11.5" y="21" width="6" height="2" rx="1" fill="#9AA6BA"/>
    </svg>
    Shortlist
  </span>
</div></header>
<main>${body}</main>
</body></html>`;

const q = $('Recruiter Page').first().json.query || {};
const recruiter = String(q["recruiter-name"] || "").slice(0, 80);
const norm = (s) => String(s ?? "").toLowerCase().trim().replace(/[^a-z0-9\u0600-\u06FF]+/g, "-").replace(/^-+|-+$/g, "");
const wanted = norm(recruiter);

const jobs = $('Get Recruiter Jobs').all().map(i => i.json)
  .filter(j => j && j.jobId && norm(j.recruiterName) === wanted);

const esc = (s) => String(s ?? "").replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

const card = (j) => {
  const jobId = String(j.jobId).trim();
  const isOpen = String(j.status).trim() === "Open";
  const badge = '<span class="badge' + (isOpen ? ' open' : '') + '">' + (isOpen ? 'Open' : esc(j.status)) + '</span>';
  const closeBtn = isOpen ? '<button class="btn btn-danger" data-close="' + esc(jobId) + '">Close job</button>' : '';
  return '<article class="job">' +
    '<div class="top"><div><h3>' + esc(j.role) + '</h3><div class="meta">Job ID <strong>' + esc(jobId) + '</strong></div></div>' + badge + '</div>' +
    '<div class="actions"><button class="btn btn-primary" data-view="' + esc(jobId) + '">View applicants</button>' + closeBtn + '</div>' +
    '</article>';
};

const openJobs = jobs.filter(j => String(j.status).trim() === "Open");
const closedJobs = jobs.filter(j => String(j.status).trim() !== "Open");

const body = '<h1>My jobs</h1>' +
  '<p class="lede">Welcome, ' + esc(recruiter) + '. Choose a job to see its applicants.</p>' +
  '<section class="panel"><div class="panel__head"><h2>Open jobs</h2></div>' +
  (openJobs.length ? '<div class="grid">' + openJobs.map(card).join("") + '</div>' : '<div class="empty">No open jobs.</div>') +
  '</section>' +
  '<section class="panel"><div class="panel__head"><h2>Closed jobs</h2></div>' +
  (closedJobs.length ? '<div class="grid">' + closedJobs.map(card).join("") + '</div>' : '<div class="empty">No closed jobs.</div>') +
  '</section>' +
  '<script>' +
  'var base = location.pathname.replace(/\\/recruiter\\/?$/, "");' +
  'document.addEventListener("click", async function(e){' +
  '  var v = e.target.getAttribute("data-view");' +
'  if (v) { location.href = base + "/job?jobId=" + encodeURIComponent(v); return; }' +
  '  var c = e.target.getAttribute("data-close");' +
  '  if (!c) return;' +
  '  if (!confirm("Close this job? New applications will be stopped.")) return;' +
  '  e.target.disabled = true;' +
  '  try {' +
  '    var r = await fetch(base + "/close-job", {method: "POST", headers: {"Content-Type": "application/json"}, body: JSON.stringify({jobId: c})});' +
  '    var d = await r.json();' +
  '    if (d.ok) { location.reload(); } else { alert((d.errors || ["Could not close the job."]).join("\\n")); e.target.disabled = false; }' +
  '  } catch (err) { alert("Could not reach the server. Please try again."); e.target.disabled = false; }' +
  '});' +
  '</script>';

return [{ json: { html: shell("My jobs", body) } }];
